def _write_to_file(self, filename, offset, body):
    with open(filename, 'rb+') as f:
        f.seek(offset)
        chunks = iter(lambda: body.read(self._IO_CHUNKSIZE), b'')
        for chunk in chunks:
            f.write(chunk)

